   227→  @SuppressWarnings("unused")
   228→  private SafeFuture<Void> validateMinimumRequestEpoch(
   229→      final DataColumnIdentifier identifier, final Optional<DataColumnSidecar> maybeSidecar) {
   230→    return maybeSidecar
   231→        .map(sidecar -> SafeFuture.completedFuture(Optional.of(sidecar.getSlot())))
   232→        .orElseGet(
   233→            () ->
   234→                combinedChainDataClient
   235→                    .getBlockByBlockRoot(identifier.blockRoot())
   236→                    .exceptionally(ThrottlingStorageQueryChannel::ignoreQueueIsFullException)
   237→                    .thenApply(maybeBlock -> maybeBlock.map(SignedBeaconBlock::getSlot)))
   238→        .thenAcceptChecked(
