   271→  private void handleError(
   272→      final ResponseCallback<DataColumnSidecar> callback, final Throwable error) {
   273→    final Throwable rootCause = Throwables.getRootCause(error);
   274→    if (rootCause instanceof RpcException) {
   275→      LOG.trace("Rejecting data column sidecars by root request", error);
   276→      callback.completeWithErrorResponse((RpcException) rootCause);
   277→    } else {
